package explorer

import (
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// cloneState is what one row of the clone list is doing.
//
// There are five, and only five, because decision 2 draws the line: the
// explorer creates what is missing and never reconciles what exists. A dirty
// working copy, a diverged branch, a stale remote — none of them is a state
// here, they belong to the workspaces view (§3.17).
type cloneState int

const (
	cloneQueued cloneState = iota
	cloneRunning
	cloneCloned
	cloneAlreadyThere
	cloneFailed
)

// cloneRow is one repository, or one group whose walk failed.
type cloneRow struct {
	path  string
	state cloneState
	// frame is the spinner's current character, stamped on while the row is
	// running. It is text rather than a rendered spinner because a table cell
	// must carry no escape sequences (Rule 122).
	frame  string
	detail string
}

// cloneList is the ModeCloning screen: the pipeline in flight and the table
// showing it. It is the progress view and the report both — decision 9 leaves
// modals for yes/no confirmations only.
type cloneList struct {
	table datatable.Model[cloneRow]
	// rows is the authoritative order: discovery order, which is the order
	// things happened. The table may sort it, but the list does not.
	rows  []cloneRow
	index map[string]int

	run    *cloneRun
	target string
	// frameIdx indexes spinner.Dot.Frames directly rather than reading the
	// view's spinner: spinner.Model.View() renders through its style, and a
	// styled string in a table cell bleeds over every row below it (Rule 122).
	frameIdx int

	// cancelling is set by `esc` and cleared by nothing: a run that is stopping
	// cannot be restarted, only awaited. A second `esc` must not force, because
	// forcing is the half-cloned directory decision 12 avoids.
	cancelling bool
	finished   bool
}

const (
	colCloneStatusMin = 16
	colClonePathMin   = 30
	colCloneDetailMin = 20
)

func newCloneList(target string, run *cloneRun) *cloneList {
	return &cloneList{
		target: target,
		run:    run,
		index:  map[string]int{},
		table: datatable.New(datatable.Config[cloneRow]{
			Columns: cloneColumns(),
			// Discovery order, deliberately: it is the order things happened, and
			// a list that reorders itself while it fills is unreadable. `.` still
			// sorts on demand.
			SortColumn: -1,
		}),
	}
}

// cloneColumns describes the clone list.
func cloneColumns() []datatable.Column[cloneRow] {
	return []datatable.Column[cloneRow]{
		{
			Title: "Status", MinWidth: colCloneStatusMin,
			Cell:  func(r cloneRow) string { return cloneStatusLabel(r) },
			Style: cloneStatusStyle,
			Less:  func(a, b cloneRow) bool { return a.state < b.state },
		},
		{
			Title: "Repository", MinWidth: colClonePathMin, Flex: 2,
			Cell:   func(r cloneRow) string { return r.path },
			Less:   func(a, b cloneRow) bool { return strings.ToLower(a.path) < strings.ToLower(b.path) },
			Search: func(r cloneRow) string { return r.path },
		},
		{
			Title: "Detail", MinWidth: colCloneDetailMin, Flex: 1,
			Cell:   func(r cloneRow) string { return r.detail },
			Search: func(r cloneRow) string { return r.detail },
		},
	}
}

// cloneStatusLabel is the status cell: an icon and a word, plain text.
func cloneStatusLabel(r cloneRow) string {
	switch r.state {
	case cloneRunning:
		return r.frame + " cloning"
	case cloneCloned:
		return theme.IconOK + " cloned"
	case cloneAlreadyThere:
		return theme.IconSkipped + " already there"
	case cloneFailed:
		return theme.IconError + " failed"
	default:
		return theme.IconPending + " queued"
	}
}

// cloneStatusStyle colours the status cell.
//
// The five states are the whole vocabulary of this screen, and they are the one
// thing a run of forty rows is read for: which ones failed, which are still
// going, which were already on disk and were left alone.
func cloneStatusStyle(r cloneRow) lipgloss.Style {
	switch r.state {
	case cloneCloned:
		return theme.StatusOKStyle
	case cloneFailed:
		return theme.StatusErrorStyle
	case cloneRunning:
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	default: // queued, and already there — neither is news
		return theme.DimStyle
	}
}

// apply folds one pipeline event into the list.
//
// An event for a path that has no row yet creates one. That is not defensive
// padding: cloneWalkFailed names a group, which was never found as a
// repository and so has no row to update.
func (l *cloneList) apply(event cloneEvent) {
	switch event.kind {
	case cloneFound:
		l.upsert(event.path, cloneQueued, "")
	case cloneBegan:
		l.upsert(event.path, cloneRunning, "")
	case cloneEnded:
		switch {
		case event.err != nil:
			l.upsert(event.path, cloneFailed, event.err.Error())
		case event.skipped:
			l.upsert(event.path, cloneAlreadyThere, "")
		default:
			l.upsert(event.path, cloneCloned, "")
		}
	case cloneWalkFailed:
		l.upsert(event.path, cloneFailed, "discovery: "+event.err.Error())
	}
	l.sync()
}

func (l *cloneList) upsert(path string, state cloneState, detail string) {
	if i, ok := l.index[path]; ok {
		l.rows[i].state = state
		l.rows[i].detail = detail
		return
	}
	l.index[path] = len(l.rows)
	l.rows = append(l.rows, cloneRow{path: path, state: state, detail: detail})
}

// advance moves the spinner shown on the running rows one frame on.
func (l *cloneList) advance() {
	l.frameIdx = (l.frameIdx + 1) % len(spinner.Dot.Frames)
	l.sync()
}

// sync hands the table a copy with the current spinner frame stamped on.
//
// The frame is stamped here rather than held on the row because it belongs to
// the list, not to any repository: one spinner, on every row that is running.
func (l *cloneList) sync() {
	frame := spinner.Dot.Frames[l.frameIdx%len(spinner.Dot.Frames)]
	items := make([]cloneRow, len(l.rows))
	copy(items, l.rows)
	for i := range items {
		if items[i].state == cloneRunning {
			items[i].frame = frame
		}
	}
	l.table.SetItems(items)
}

// running counts the clones still in flight, which is what `esc` has to wait
// for and what the view states while it does.
func (l *cloneList) running() int {
	n := 0
	for _, r := range l.rows {
		if r.state == cloneRunning {
			n++
		}
	}
	return n
}

// counts is the header line: what has been found and how it went.
func (l *cloneList) counts() (found, cloned, present, failed int) {
	for _, r := range l.rows {
		found++
		switch r.state {
		case cloneCloned:
			cloned++
		case cloneAlreadyThere:
			present++
		case cloneFailed:
			failed++
		case cloneQueued, cloneRunning:
		}
	}
	return found, cloned, present, failed
}

// failures returns the failed paths, for the log and the footer. Decision 13
// discards the list on `esc`, and workspaces records only the successes — a
// failure that wrote nothing leaves nothing behind, so it has to be said while
// the view is still alive.
func (l *cloneList) failures() []string {
	var out []string
	for _, r := range l.rows {
		if r.state == cloneFailed {
			out = append(out, r.path)
		}
	}
	return out
}

package ociresources

import (
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// browserState tracks which screen the browser is on.
type browserState int

// browserStateResolving is gone. The browser used to open into it and ignore
// every key — esc included — while up to one 8-second detection per configured
// registry ran (D13). Members now come from config plus the group cache, so
// there is nothing to resolve and the form renders at once, offline included.
const (
	browserStateInput  browserState = iota // search form
	browserStateTags                       // results table
	browserStateStatus                     // spinner during pull
)

// browserRegistryEntry is one selectable registry in the browser form.
// Group members have ParentSlug set; standalone registries have it empty.
type browserRegistryEntry struct {
	URL   string
	Alias string
	// Slug identifies the entry: its own for a standalone registry, its group's
	// for a member. It is what the result filter resolves labels through, and
	// what replaced matching on URL — two registries configured with the same
	// URL used to collide.
	Slug        string
	ParentAlias string // non-empty = member of a group
	ParentSlug  string
	parentURL   string // URL of the parent RegistryItem (for credential lookup)
	// key identifies the entry among all the others, and is what the checkbox
	// and the remembered exclusions are keyed on (D40). It is not the URL: two
	// registries may be declared on one host — the form enforces slug
	// uniqueness, not URL uniqueness — and §3.18 makes that the ordinary case.
	// Nor is it Slug, which holds the *group's* slug for a member and would
	// give a whole group one checkbox. So: the slug for a standalone registry,
	// and the group's slug plus the member's URL for a member, the URL being
	// what tells two members of one group apart. Their aliases do not:
	// cleanMemberAlias strips `-proxy` and `-hosted`, so `docker-io-proxy` and
	// `docker-io-hosted` both display as `docker-io`.
	key string
	// authMode is already resolved: a member carries what its group settled on,
	// since `inherit` is the only thing the shared credential entry can mean.
	authMode string
}

// resultFilter narrows the tag table to one group or one registry. Both empty
// means everything.
type resultFilter struct {
	groupSlug string
	url       string
}

func (f resultFilter) isEmpty() bool { return f.groupSlug == "" && f.url == "" }

// matches reports whether a result from url passes the filter. A group matches
// every member's URL, which is what the group level is for.
func (f resultFilter) matches(url string, entry *browserRegistryEntry) bool {
	switch {
	case f.isEmpty():
		return true
	case f.groupSlug != "":
		return entry != nil && entry.ParentSlug == f.groupSlug
	default:
		return url == f.url
	}
}

// pickerRow is one line of the registry picker. A group is a row of its own
// whose checkbox covers its members, which is the only way to select eight
// proxies without eight keystrokes.
type pickerRow struct {
	// groupSlug is set on a group header; entry is -1 there.
	groupSlug string
	label     string
	entry     int // index into b.entries, or -1
}

const brFieldRepo = 0

// brFieldReg returns the form field index for the i-th picker row.
func (b *RegistryBrowser) brFieldReg(i int) int { return 1 + i }

// brFieldSubmit returns the form field index for the Browse Tags button.
func (b *RegistryBrowser) brFieldSubmit() int { return 1 + len(b.rows) }

// RegistryBrowserCloseMsg is sent when the user presses ESC on the browser input screen.
type RegistryBrowserCloseMsg struct{}

// tagSortField selects which column to sort the tag list by.
type tagSortField int

const (
	tagSortByName    tagSortField = iota
	tagSortByUpdated              // newest first
)

// RegistryBrowser searches image tags across multiple configured registries.
type RegistryBrowser struct {
	registries    []config.RegistryItem
	width, height int

	// Entries, built once from config plus the group cache.
	entries []browserRegistryEntry
	rows    []pickerRow

	// Form state
	repoInput    textinput.Model
	selectedRegs map[string]bool // entry key → checked
	focusedField int

	// Results state
	tags              []MultiRegistryTag
	pendingSearches   int
	registryFilter    resultFilter
	tagTable          table.Model
	scanCache         map[string]cache.ImageScanEntry
	scanningTags      map[string]bool
	tagScanSpinnerIdx int

	// Tag filter/sort in results view
	filterInput  textinput.Model
	filterActive bool
	tagSortCol   tagSortField
	tagSortDesc  bool

	// Status screen (pull operation)
	spinner   spinner.Model
	operation string
	imageName string

	state browserState
}

// newRegistryBrowser creates a RegistryBrowser showing its form immediately.
//
// A group's members come from the cache the Registries tab refreshes, so
// opening the browser reads a file rather than the network — which is what
// removed the resolving state D13 is about, rather than papering over it.
func newRegistryBrowser(
	registries []config.RegistryItem,
	groups map[string]cache.RegistryGroupEntry,
	deselected map[string]bool,
	width, height int,
) *RegistryBrowser {
	repoInput := textinput.New()
	repoInput.Placeholder = "nginx  (or library/nginx)"
	repoInput.CharLimit = 256
	theme.StyleTextInput(&repoInput)
	repoInput.Focus()

	fi := textinput.New()
	fi.Placeholder = "filter tags…"
	fi.CharLimit = 128
	theme.StyleTextInput(&fi)

	tagCols := []table.Column{
		{Title: "Registry", Width: 20},
		{Title: "Tag", Width: 30},
		{Title: "Updated", Width: 16},
		{Title: "C", Width: 4},
		{Title: "H", Width: 4},
		{Title: "M", Width: 4},
		{Title: "L", Width: 4},
	}
	tt := table.New(
		table.WithColumns(tagCols),
		table.WithFocused(true),
		table.WithHeight(10),
	)
	tt.SetStyles(theme.DefaultTableStyles())

	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	b := &RegistryBrowser{
		registries:   registries,
		width:        width,
		height:       height,
		repoInput:    repoInput,
		selectedRegs: make(map[string]bool),
		focusedField: brFieldRepo,
		filterInput:  fi,
		tagSortCol:   tagSortByName,
		tagSortDesc:  false,
		tagTable:     tt,
		spinner:      sp,
		scanCache:    make(map[string]cache.ImageScanEntry),
		scanningTags: make(map[string]bool),
		state:        browserStateInput,
	}
	b.buildEntries(groups, deselected)
	b.resizeInputs()
	b.resizeTagTable()
	b.updateFocus()
	return b
}

// buildEntries expands every configured registry into the lines the picker
// shows: a group into its cached members under a header, anything else into
// itself.
//
// A selection is remembered as the entries that were *un*checked, so a member
// discovered since the last visit arrives checked like every other new one.
func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntry, deselected map[string]bool) {
	b.entries = nil
	b.rows = nil
	for _, reg := range b.registries {
		alias := browserAlias(reg)
		// Members share their group's host and therefore its single credential
		// entry, so they share the decision the group made about using it.
		mode := config.ResolveAuthMode(reg, nil)

		members := groups[reg.Slug].Members
		if reg.Kind != config.KindGroup || len(members) == 0 {
			// A group nobody has discovered yet is offered as itself: it is a
			// pullable registry too, and hiding it would be worse than listing
			// it without the members it may have.
			b.rows = append(b.rows, pickerRow{label: alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL: reg.URL, Alias: alias, Slug: reg.Slug, authMode: mode,
				key: reg.Slug,
			})
			continue
		}

		b.rows = append(b.rows, pickerRow{groupSlug: reg.Slug, label: alias, entry: -1})
		for _, m := range members {
			b.rows = append(b.rows, pickerRow{label: "  " + m.Alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL:         m.URL,
				Alias:       m.Alias,
				Slug:        reg.Slug,
				ParentAlias: alias,
				ParentSlug:  reg.Slug,
				parentURL:   reg.URL,
				authMode:    mode,
				key:         memberKey(reg.Slug, m.URL),
			})
		}
	}

	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.key] = !deselected[e.key]
	}
}

// memberKey names one member of a group. Scoping it by the group's slug is what
// keeps two groups fronting the same repository apart, and what keeps a member
// from colliding with a standalone registry keyed on its own slug.
func memberKey(groupSlug, memberURL string) string {
	return groupSlug + "/" + memberURL
}

// browserAlias returns what a registry is labelled with in the browser.
func browserAlias(reg config.RegistryItem) string {
	if reg.Alias != "" {
		return reg.Alias
	}
	return reg.URL
}

// selected reports whether an entry is checked.
func (b *RegistryBrowser) selected(e browserRegistryEntry) bool { return b.selectedRegs[e.key] }

// groupState reports whether all, none or some of a group's members are checked.
func (b *RegistryBrowser) groupState(slug string) theme.CheckState {
	checked, total := 0, 0
	for _, e := range b.entries {
		if e.ParentSlug != slug {
			continue
		}
		total++
		if b.selected(e) {
			checked++
		}
	}
	switch {
	case total == 0 || checked == 0:
		return theme.CheckNone
	case checked == total:
		return theme.CheckAll
	default:
		return theme.CheckSome
	}
}

// toggleGroup checks every member of a group, or unchecks them when they were
// all already checked. A partial selection resolves upwards: the user is more
// likely to be completing it than discarding it.
func (b *RegistryBrowser) toggleGroup(slug string) {
	want := b.groupState(slug) != theme.CheckAll
	for _, e := range b.entries {
		if e.ParentSlug == slug {
			b.selectedRegs[e.key] = want
		}
	}
}

// Deselected returns the keys of the entries the user unchecked, which is what
// is remembered between visits.
func (b *RegistryBrowser) Deselected() []string {
	var out []string
	for _, e := range b.entries {
		if !b.selected(e) {
			out = append(out, e.key)
		}
	}
	return out
}

// SetSize updates dimensions and resizes internal components.
func (b *RegistryBrowser) SetSize(width, height int) {
	b.width = width
	b.height = height
	b.resizeInputs()
	b.resizeTagTable()
}

func (b *RegistryBrowser) resizeInputs() {
	w := max(b.width-22, 20)
	b.repoInput.Width = w
	b.filterInput.Width = max(b.width-6, 10)
}

func (b *RegistryBrowser) resizeTagTable() {
	b.tagTable.SetHeight(max(b.height, 1))

	// b.width is already the viewport content width (full width - 2 borders).
	// Subtract only the cell padding (numCols × 2) so column widths sum exactly to `available`.
	const numCols = 7
	available := max(b.width-numCols*2, 10)
	fixedReg := 20
	fixedUpdated := 16
	fixedC, fixedH, fixedM := 4, 4, 4
	fixedSum := fixedReg + fixedUpdated + fixedC + fixedH + fixedM
	flexTag := max(available-fixedSum-4, 8) // reserve 4 for last col minimum

	cols := b.tagTable.Columns()
	if len(cols) == numCols {
		cols[0].Width = fixedReg
		cols[1].Width = flexTag
		cols[2].Width = fixedUpdated
		cols[3].Width = fixedC
		cols[4].Width = fixedH
		cols[5].Width = fixedM
		// Last column absorbs leftover so sum(col_widths) == available exactly.
		cols[6].Width = available - fixedReg - flexTag - fixedUpdated - fixedC - fixedH - fixedM
		b.tagTable.SetColumns(cols)
	}

	// Force the Selected row style to span the viewport content width so the selected
	// background extends to the right border, even when row content visually differs
	// from the calculated width (e.g. Nerd Font icon width discrepancies). See workspaces fix.
	styles := theme.DefaultTableStyles()
	styles.Selected = styles.Selected.Width(b.width)
	b.tagTable.SetStyles(styles)
}

